#include "Recorder.h"
static bool longAudioFile(const File& file){
    file.getParentDirectory().createDirectory();TemporaryFile temporary(file);std::unique_ptr<OutputStream> stream(temporary.getFile().createOutputStream());WavAudioFormat format;
    auto writer=stream?format.createWriterFor(stream,AudioFormatWriterOptions{}.withSampleRate(8000).withNumChannels(1).withBitsPerSample(32).withSampleFormat(AudioFormatWriterOptions::SampleFormat::floatingPoint)):nullptr;if(!writer)return false;
    AudioBuffer<float> block(1,4096);for(int pos=0;pos<8000*420;pos+=4096){int n=jmin(4096,8000*420-pos);for(int i=0;i<n;++i)block.setSample(0,i,pos+i>=8000*240?.31f:pos+i>=8000*120?.17f:.05f);if(!writer->writeFromAudioSampleBuffer(block,0,n))return false;}writer.reset();stream.reset();return temporary.overwriteTargetFileWithTemporary();
}
static void testLongAudio(const File& root){
    auto file=root.getChildFile("long-audio-source.wav");expect(longAudioFile(file),"create seven-minute mono voice-shaped source beyond the old two-minute cap");Assets assets;String error;auto* sample=assets.load(file,error);
    expect(sample&&sample->audio.getNumSamples()==8000*420&&sample->audio.getSample(0,8000*300)==.31f&&sample->audio.getSample(1,8000*300)==.31f,"long source decodes its full tail and duplicates mono correctly");auto remaining=assets.availableBytes();expect(sample&&remaining==maxDecodedAudioBytes-8000ull*420*8&&assets.load(file,error)==sample&&remaining==assets.availableBytes(),"long-source cache remains bounded and repeated references share a single decode");
    auto p=emptyProject();p.songMode=true;p.loop=false;p.bpm=120;p.master=1;p.delayReturn=0;p.patterns[0].length=4;auto& track=p.tracks[7];track.volume=1;track.cutoff=20000;track.send=0;Clip clip;clip.track=7;clip.audioPath=file.getFullPathName();clip.beat=0;clip.length=840;p.clips.push_back(clip);Project loaded;
    expect(projectFromJson(projectToJson(p),loaded).wasOk()&&(int)projectToJson(p)["schema"]==25&&loaded.clips[0].length==840&&loaded.patterns[0].length==4,"schema25 preserves a full-song audio clip independently of short pattern length");auto legacy=projectToJson(p);legacy.getDynamicObject()->setProperty("schema",24);auto prior=JSON::toString(projectToJson(loaded));expect(projectFromJson(legacy,loaded).failed()&&JSON::toString(projectToJson(loaded))==prior,"legacy schema rejects long-clip bounds instead of silently shortening them");
    auto engine=makeEngine(p,assets,root);engine->prepare(8000);engine->seekRequested=600;AudioBuffer<float> block(2,512);engine->render(block.getWritePointer(0),block.getWritePointer(1),512);
    expect(engine->playing.load()&&engine->position.load()>600&&std::abs(block.getSample(0,400)-.31f/std::sqrt(2.f))<1e-4,"Song seeking reaches the real five-minute source tail rather than retriggering its first pattern chunk");
    p.clips[0].sourceOffset=300;p.clips[0].length=2;p.tracks[7].sampleStart=300;p.tracks[7].sampleEnd=360;expect(projectFromJson(projectToJson(p),loaded).wasOk()&&loaded.clips[0].sourceOffset==300&&loaded.tracks[7].sampleEnd==360,"long source offsets and sampler ranges survive project save/load");
    p.clips[0].sourceOffset=0;p.clips[0].length=840;storeSongMarker(p,{"voice","Voice",0,840,1});SectionClipStats stats;expect(inspectSectionClips(p,"voice",stats).wasOk(),"section tools accept long audio clips with unchanged automation/pattern limits");
    Project sliced;expect(sliceWaveFramesToPlaylist(p,7,file.getFullPathName(),8000,8000*420,{8000*300,8000*301},1000,sliced).wasOk()&&sliced.clips.back().sourceOffset==300,"non-destructive slicing can address audio after the old 120-second boundary");
    RenderSettings settings;settings.source=RenderSource::song;settings.startBeat=600;settings.endBeat=602;settings.tailSeconds=0;settings.bits=32;settings.sampleRate=48000;auto output=root.getChildFile("long-audio-tail-export.wav");expect(renderAudio(p,assets,root,output,settings).wasOk(),"offline Song export includes selected full-song audio after five minutes");
    AudioFormatManager fm;fm.registerBasicFormats();std::unique_ptr<AudioFormatReader> reader(fm.createReaderFor(output));AudioBuffer<float> read(2,4096);expect(reader&&reader->read(&read,0,4096,0,true,true)&&read.getMagnitude(0,1000,3000)>.2f,"exported long-source tail contains real late-file audio");
    for(double limit:{120.,131.}){Recorder recorder;auto destination=root.getNonexistentChildFile("long-take-"+String((int)limit),".wav");expect(recorder.start(destination,8000,1,limit).wasOk(),"disk recorder accepts explicit selectable take length");AudioBuffer<float> input(1,1024);for(int i=0;i<1024;++i)input.setSample(0,i,.2f);int frames=(int)(8000*(limit+1));for(int pos=0;pos<frames;pos+=1024){recorder.capture(input.getReadPointer(0),nullptr,jmin(1024,frames-pos));Thread::sleep(1);}expect(recorder.frames()==(uint64_t)(limit*8000)&&recorder.reachedLimit()&&recorder.limitSeconds()==limit,"streaming take stops at its exact selected frame limit, including beyond two minutes");expect(recorder.finish().wasOk(),"long recording flushes and closes without overflow");reader.reset(fm.createReaderFor(destination));expect(reader&&reader->lengthInSamples==(int64)(limit*8000)&&reader->numChannels==1&&reader->bitsPerSample==24,"long take WAV retains every captured frame and mono/24-bit format");}
    Recorder invalid;auto dest=root.getNonexistentChildFile("invalid-long-take",".wav");expect(invalid.start(dest,8000,1,0).failed()&&invalid.start(dest,8000,1,1801).failed()&&invalid.start(dest,std::numeric_limits<double>::quiet_NaN(),1).failed()&&!dest.exists(),"invalid take duration/rate rejects before creating any file");
}
